CREATE OR REPLACE FUNCTION "ponder_go_srcsync_18e1c6e0bdf38fc0"."_ponder_go_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'TRUNCATE is unsupported for onchain tables'; END IF;
